import { createMiddleware } from "@tanstack/react-start";

// Must be registered as a global `functionMiddleware` in `src/start.ts`; otherwise
// the browser never attaches the bearer token to serverFn RPCs.
//
// NOTE (local edit): the Supabase client is imported dynamically on purpose.
// A static `import { supabase } from "./client"` pulls the whole Supabase SDK
// into the *public* entry chunk (~50 kB gzip) even though no public page uses
// it. Dynamic import keeps it in its own chunk, loaded only if a server
// function actually runs. If Lovable regenerates this file, re-apply the
// `await import(...)` form and re-check `npm run build` chunk sizes.
export const attachSupabaseAuth = createMiddleware({ type: "function" }).client(
  async ({ next }) => {
    const { supabase } = await import("./client");
    const { data } = await supabase.auth.getSession();
    const token = data.session?.access_token;
    return next({
      headers: token ? { Authorization: `Bearer ${token}` } : {},
    });
  },
);
